window.QUESTION_BANK=[{"id":"Q001","area":"Linguagens","subject":"Português","topic":"Interpretação de textos","context":"Em uma ação de conscientização ambiental, um cartaz apresenta a mensagem: “A torneira não sabe quando você precisa de água. Você sabe quando precisa fechá-la.” O texto circula em escolas e repartições públicas.","stem":"O efeito persuasivo da campanha se constrói principalmente pela","options":["apresentação de uma pesquisa científica sobre consumo doméstico.","personificação da torneira para atribuir responsabilidade ao leitor.","comparação matemática entre diferentes tarifas de água.","defesa de que somente governos devem economizar recursos.","substituição da linguagem verbal por sinais exclusivamente visuais."],"answer":1,"explanation":"A personificação (“a torneira não sabe”) cria contraste com o conhecimento e a responsabilidade humana, mobilizando o leitor a agir.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q002","area":"Linguagens","subject":"Português","topic":"Interpretação multimodal","context":"Um boletim de uma biblioteca municipal registrou o número de livros emprestados ao longo de quatro meses. A campanha de incentivo à leitura começou em março.","stem":"Considerando os dados do gráfico, qual conclusão é diretamente sustentada por eles?","options":["O número de empréstimos caiu após o início da campanha.","O mês de fevereiro apresentou o maior volume de empréstimos.","O crescimento entre março e abril foi de 100 livros.","Abril teve mais empréstimos do que janeiro e fevereiro juntos.","Os empréstimos aumentaram de fevereiro para março e de março para abril."],"answer":4,"explanation":"O gráfico apresenta janeiro=120, fevereiro=100, março=150 e abril=190. Houve crescimento de fevereiro a março e novamente de março a abril; a soma de janeiro e fevereiro é 220, maior que 190.","visual":{"type":"bar","title":"Empréstimos mensais na biblioteca","labels":["Jan","Fev","Mar","Abr"],"values":[120,100,150,190],"unit":"livros"},"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q003","area":"Linguagens","subject":"Português","topic":"Gêneros textuais","context":"Em um aplicativo de transporte, o usuário encontra o aviso: “Seu veículo chegará em aproximadamente 6 minutos. Confirme o local de embarque e mantenha o celular por perto”.","stem":"Nesse contexto, a função principal do aviso é","options":["narrar ficcionalmente a viagem de um personagem.","defender uma tese política sobre mobilidade urbana.","orientar o comportamento do usuário em uma situação prática.","produzir humor por meio de ambiguidades intencionais.","apresentar uma crítica literária de um serviço."],"answer":2,"explanation":"O texto instrui o usuário sobre procedimentos ligados a uma situação concreta de uso do aplicativo.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q004","area":"Linguagens","subject":"Português","topic":"Variação linguística","context":"Uma estudante escreveu em mensagem para colegas: “A gente se vê depois da aula”. Em um relatório escolar, optou por “Nós nos encontraremos após a aula”. Ambas as formas cumprem seu propósito comunicativo.","stem":"A mudança de registro revela","options":["adequação das escolhas linguísticas aos interlocutores e às situações.","que a linguagem informal não apresenta regularidades gramaticais.","que a norma-padrão deve ser obrigatória em qualquer conversa.","que variedades da língua não podem coexistir em uma sociedade.","que o português muda somente por razões geográficas."],"answer":0,"explanation":"Diferentes situações pedem diferentes graus de formalidade; o uso de uma variedade não implica inferioridade de outra.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q005","area":"Linguagens","subject":"Português","topic":"Coesão e conectivos","context":"“O município ampliou a coleta seletiva. ______, a quantidade de resíduos enviados aos aterros permaneceu elevada, pois a participação dos moradores ainda era baixa.”","stem":"Qual conectivo preenche a lacuna mantendo a relação de oposição entre as informações?","options":["Portanto","Porque","Além disso","Entretanto","Assim"],"answer":3,"explanation":"“Entretanto” marca contraste: houve expansão da coleta seletiva, mas o volume destinado a aterros continuou alto.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q006","area":"Linguagens","subject":"Português","topic":"Ironia e efeitos de sentido","context":"Em uma postagem, uma pessoa fotografa uma rua totalmente alagada e escreve: “Uma ótima piscina pública, inaugurada depois de quinze minutos de chuva”. A legenda acompanha uma crítica à infraestrutura urbana.","stem":"O efeito de sentido predominante é a","options":["neutralidade informativa, com descrição objetiva da rua.","ironia, ao elogiar aparentemente uma situação problemática.","defesa literal de novas piscinas no espaço urbano.","reprodução fiel de uma propaganda turística.","comparação científica dos níveis de precipitação."],"answer":1,"explanation":"A legenda usa elogio aparente para criticar alagamentos e problemas de drenagem.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q007","area":"Linguagens","subject":"Literatura","topic":"Modernismo brasileiro","context":"Em um poema do século XX, um eu lírico incorpora expressões coloquiais, cenas corriqueiras e uma visão crítica dos costumes, rompendo com o vocabulário excessivamente solene de tradições anteriores.","stem":"Esse procedimento se aproxima de uma característica importante do Modernismo brasileiro: ","options":["a defesa da imitação rígida de modelos clássicos.","a proibição de temas urbanos na literatura.","a valorização exclusiva dos padrões europeus.","o abandono de toda referência à cultura brasileira.","a experimentação estética e a aproximação da língua cotidiana."],"answer":4,"explanation":"O Modernismo brasileiro explorou experimentação formal e linguagem cotidiana, entre outras estratégias de renovação estética.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q008","area":"Linguagens","subject":"Artes","topic":"Arte e patrimônio","context":"Um grupo de artistas urbanos transforma um muro abandonado em um painel com imagens da memória de moradores do bairro. O projeto inclui entrevistas com antigos trabalhadores e crianças da comunidade.","stem":"Nessa intervenção, a arte atua principalmente como","options":["substituta obrigatória dos documentos oficiais.","mecanismo de apagamento das diferenças culturais.","meio de valorização da memória coletiva e de pertencimento.","atividade que impede a participação da comunidade.","recurso para tornar idênticas todas as narrativas do bairro."],"answer":2,"explanation":"A arte pública pode dar visibilidade às histórias locais e fortalecer a identidade coletiva.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q009","area":"Linguagens","subject":"Português","topic":"Intertextualidade","context":"Uma campanha de vacinação adapta a frase conhecida “Quem tem boca vai a Roma” para “Quem tem informação vai se proteger”. A construção recupera uma expressão familiar ao público.","stem":"O principal recurso utilizado é","options":["intertextualidade, com reformulação de um enunciado conhecido.","citação acadêmica formal com indicação de página.","uso de linguagem técnica exclusiva de profissionais da saúde.","negação de qualquer vínculo com discursos anteriores.","descrição impessoal de um procedimento laboratorial."],"answer":0,"explanation":"A campanha dialoga com um ditado popular, alterando-o para produzir novo sentido.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q010","area":"Linguagens","subject":"Português","topic":"Argumentação","context":"Em um artigo de opinião, lê-se: “É necessário investir em bibliotecas públicas, porque esses espaços oferecem acesso gratuito ao conhecimento e reduzem barreiras educacionais”.","stem":"A parte iniciada por “porque” funciona como","options":["repetição da tese sem novos elementos.","marcador de tempo que organiza uma sequência narrativa.","oposição à proposta de ampliar bibliotecas.","justificativa para o posicionamento defendido.","uma pergunta cuja resposta fica em aberto."],"answer":3,"explanation":"A oração apresenta a razão usada para sustentar a tese de investir em bibliotecas.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q011","area":"Linguagens","subject":"Inglês","topic":"Leitura em língua estrangeira","context":"No mural de uma universidade, aparece o aviso: “Bring your own bottle. Water refill stations are available throughout the campus. Small actions reduce plastic waste.”","stem":"A mensagem em inglês incentiva os estudantes a","options":["comprar novas garrafas descartáveis todos os dias.","levar garrafas reutilizáveis e evitar resíduos plásticos.","parar de beber água durante as atividades.","substituir o abastecimento de água por bebidas industrializadas.","usar apenas garrafas de vidro compradas na universidade."],"answer":1,"explanation":"“Bring your own bottle” pede que cada um leve sua garrafa; “refill stations” são pontos de reabastecimento e “reduce plastic waste” significa reduzir resíduos plásticos.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q012","area":"Linguagens","subject":"Espanhol","topic":"Leitura em língua estrangeira","context":"Um aviso em uma estação de trem informa: “Por motivos de mantenimiento, los trenes saldrán del andén 4 hasta nuevo aviso. Consulte los paneles antes de viajar”.","stem":"O comunicado orienta os passageiros a","options":["deixar de usar o transporte ferroviário indefinidamente.","comprar passagens no guichê número quatro.","ignorar os painéis da estação.","esperar a chegada dos trens em qualquer plataforma.","verificar a mudança temporária da plataforma de embarque."],"answer":4,"explanation":"“Los trenes saldrán del andén 4” indica que os trens sairão da plataforma 4; os painéis devem ser consultados.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q013","area":"Linguagens","subject":"Português","topic":"Linguagem verbal e não verbal","context":"Um infográfico sobre descarte de lixo eletrônico combina o desenho de um telefone quebrado, o símbolo de reciclagem e a frase “Não jogue seu futuro no lixo: procure um ponto de coleta”.","stem":"O uso combinado de imagem, símbolo e texto contribui para","options":["apagar a função persuasiva do cartaz.","exigir leitura exclusivamente técnica do público.","reforçar visualmente a orientação sobre o descarte adequado.","demonstrar que imagens substituem toda comunicação verbal.","transformar uma campanha em texto narrativo literário."],"answer":2,"explanation":"Elementos visuais e verbais se complementam para orientar o público sobre a destinação do lixo eletrônico.","visual":{"type":"poster","kind":"ewaste"},"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q014","area":"Linguagens","subject":"Educação Física","topic":"Práticas corporais e saúde","context":"Uma escola substituiu a proposta de “escolher apenas os melhores atletas” por aulas com diferentes jogos, ritmos, esportes adaptados e atividades escolhidas coletivamente.","stem":"A mudança amplia a educação física ao favorecer","options":["participação, diversidade e acesso às práticas corporais.","seleção precoce de talentos como único objetivo educacional.","eliminação das diferenças entre estudantes por competição.","restrição das aulas a resultados esportivos profissionais.","exclusão de práticas culturais não competitivas."],"answer":0,"explanation":"A abordagem inclusiva valoriza diversidade cultural, participação e o direito de experimentar diferentes práticas corporais.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q015","area":"Linguagens","subject":"Português","topic":"Funções da linguagem","context":"Em uma oficina de escrita, a professora pede: “Observe como a palavra ‘tempo’ aparece repetida e como o ritmo dessa repetição modifica a leitura do poema”.","stem":"A atividade destaca principalmente a função","options":["referencial, por privilegiar dados estatísticos.","fática, por testar o canal de comunicação.","conativa, por orientar uma compra.","poética, por focalizar a construção formal da mensagem.","metalinguística, por traduzir um vocábulo estrangeiro."],"answer":3,"explanation":"A função poética destaca a forma e os recursos expressivos do próprio texto, como ritmo e repetição.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q016","area":"Linguagens","subject":"Português","topic":"Leitura crítica de publicidade","context":"Uma propaganda de curso promete: “Aprenda uma língua em sete dias, sem esforço e com resultado garantido”. A peça não apresenta método, resultados comparativos nem condições para a garantia.","stem":"Uma leitura crítica dessa publicidade deve reconhecer que","options":["toda afirmação publicitária corresponde necessariamente a um resultado comprovado.","a ausência de evidências torna a promessa algo a ser verificado, não um fato demonstrado.","o uso de números garante a credibilidade científica da mensagem.","uma promessa comercial não exerce influência sobre o consumidor.","a linguagem persuasiva impede qualquer análise da informação."],"answer":1,"explanation":"A promessa usa linguagem persuasiva, mas carece de evidências e critérios para sustentar seu caráter absoluto.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q017","area":"Humanas","subject":"História","topic":"Brasil Colonial e escravidão","context":"Na economia açucareira colonial, grandes propriedades utilizavam trabalho escravizado e orientavam a produção ao mercado externo. Os lucros se articulavam ao comércio atlântico e ao poder da metrópole.","stem":"Essa organização econômica expressa sobretudo","options":["predomínio de pequenas propriedades e produção familiar de subsistência.","rejeição ao trabalho compulsório na sociedade colonial.","isolamento do Brasil em relação às redes comerciais atlânticas.","a estrutura da plantation, com latifúndio, monocultura e exploração do trabalho.","distribuição equilibrada da renda entre trabalhadores e proprietários."],"answer":3,"explanation":"A plantation reunia grandes extensões de terra, monocultura exportadora e trabalho escravizado.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q018","area":"Humanas","subject":"História","topic":"Resistências à escravidão","context":"Comunidades formadas por pessoas que fugiam do cativeiro desenvolveram formas próprias de organização social, produção agrícola, proteção e resistência. O Quilombo dos Palmares é um exemplo histórico expressivo.","stem":"Essas comunidades evidenciam","options":["a ausência de conflitos na ordem colonial.","a participação ativa de escravizados e libertos na resistência à escravidão.","o apoio permanente de todos os senhores de engenho.","a aceitação universal do trabalho compulsório.","o fim do tráfico atlântico no início da colonização."],"answer":1,"explanation":"Quilombos representaram diversas formas de resistência e construção de autonomia diante do regime escravista.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q019","area":"Humanas","subject":"História","topic":"Independência e cidadania","context":"A Independência do Brasil, em 1822, rompeu a ligação política colonial com Portugal. Entretanto, muitas estruturas econômicas e sociais, inclusive o trabalho escravizado, permaneceram.","stem":"O processo pode ser interpretado como","options":["mudança política sem transformação imediata de todas as hierarquias sociais.","reforma que aboliu integralmente a escravidão no mesmo ano.","ruptura que distribuiu terras a todos os trabalhadores.","movimento que eliminou os conflitos entre elites regionais.","substituição imediata da monarquia por uma república democrática."],"answer":0,"explanation":"A separação política de Portugal não produziu, por si, a igualdade social nem extinguiu o trabalho escravizado.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q020","area":"Humanas","subject":"História","topic":"Industrialização","context":"No século XIX, a expansão das fábricas alterou jornadas, formas de habitação e relações de trabalho. Trabalhadores passaram a organizar associações e greves em busca de melhores condições.","stem":"Esse cenário evidencia uma relação entre industrialização e","options":["eliminação imediata da desigualdade salarial.","redução completa da migração para as cidades.","desaparecimento dos conflitos trabalhistas.","substituição de todas as máquinas por trabalho doméstico.","formação de movimentos coletivos de reivindicação de direitos."],"answer":4,"explanation":"O crescimento do trabalho fabril foi acompanhado de organização operária e movimentos por direitos.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q021","area":"Humanas","subject":"História","topic":"Era Vargas","context":"No Brasil da década de 1930 e dos anos seguintes, o Estado assumiu papel relevante na organização das relações trabalhistas e na industrialização. Essa atuação coexistiu com mecanismos autoritários, especialmente no Estado Novo.","stem":"Uma interpretação adequada do período reconhece","options":["a ausência de políticas para o trabalho urbano.","o enfraquecimento completo da ação estatal na economia.","a coexistência de direitos trabalhistas institucionalizados e centralização política.","a implantação permanente do voto universal sem restrições.","o abandono de toda política de industrialização nacional."],"answer":2,"explanation":"O período varguista combinou ampliação de marcos trabalhistas, intervenção estatal e autoritarismo, sobretudo entre 1937 e 1945.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q022","area":"Humanas","subject":"História","topic":"Ditadura Militar","context":"Documentos da segunda metade do século XX registram restrições às liberdades políticas, censura e perseguição a opositores durante o regime militar brasileiro (1964–1985).","stem":"Esses registros indicam","options":["ampliação irrestrita das liberdades civis durante todo o regime.","ausência de oposição organizada e de movimentos sociais.","substituição do Estado por organizações comunitárias.","limitações à participação democrática e à liberdade de expressão.","fim do controle estatal sobre a comunicação."],"answer":3,"explanation":"A censura e a perseguição política são características documentadas do período autoritário.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q023","area":"Humanas","subject":"História","topic":"Constituição de 1988","context":"A Constituição Federal de 1988 consolidou direitos civis, políticos e sociais no contexto da redemocratização, após duas décadas de ditadura militar.","stem":"O apelido “Constituição Cidadã” destaca","options":["o retorno ao voto censitário como princípio político.","a ampliação de direitos e garantias fundamentais.","a supressão de mecanismos de participação social.","a eliminação do direito de associação.","a restrição dos direitos trabalhistas ao setor industrial."],"answer":1,"explanation":"O texto constitucional de 1988 ampliou direitos e garantias, consolidando a ordem democrática.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q024","area":"Humanas","subject":"Geografia","topic":"Urbanização e enchentes","context":"Uma cidade registrou aumento da área asfaltada e redução de parques urbanos em dez anos. Após chuvas intensas, cresceram as ocorrências de enxurradas em bairros densamente construídos.","stem":"Uma relação geográfica coerente com essa mudança é","options":["a impermeabilização reduz a infiltração e aumenta o escoamento superficial.","o asfalto aumenta necessariamente a absorção de água pelo solo.","a retirada de vegetação elimina os riscos de erosão.","a impermeabilização reduz a velocidade da água em todas as ruas.","o crescimento urbano dispensa planejamento de drenagem."],"answer":0,"explanation":"Superfícies impermeáveis dificultam a infiltração e podem intensificar enxurradas e alagamentos.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q025","area":"Humanas","subject":"Geografia","topic":"Leitura de dados e população","context":"Um município publicou a evolução da população residente em bairros A, B e C no período de dez anos. O gráfico apresenta o número de moradores em milhares.","stem":"O bairro com o maior aumento absoluto de moradores entre o início e o fim do período foi","options":["o bairro A, com 5 mil moradores.","o bairro B, com 20 mil moradores.","o bairro C, com 15 mil moradores.","o bairro A, com 12 mil moradores.","o bairro B, com 5 mil moradores."],"answer":1,"explanation":"Bairro A: 20→32 (+12); B: 15→35 (+20); C: 30→45 (+15). O maior aumento absoluto foi de 20 mil no bairro B.","visual":{"type":"grouped","title":"População por bairro (milhares)","labels":["A","B","C"],"series":[{"name":"Ano inicial","values":[20,15,30]},{"name":"Ano final","values":[32,35,45]}],"unit":"mil habitantes"},"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q026","area":"Humanas","subject":"Geografia","topic":"Globalização produtiva","context":"Uma fabricante de aparelhos eletrônicos projeta o produto em um país, compra componentes em outros dois, monta em um terceiro e o vende em diferentes continentes.","stem":"Esse exemplo revela","options":["fim do comércio internacional e da circulação de capitais.","produção concentrada exclusivamente no mercado local.","integração de cadeias produtivas em diferentes territórios.","desaparecimento da divisão internacional do trabalho.","impossibilidade de articulação entre empresas e países."],"answer":2,"explanation":"A produção distribuída entre países evidencia cadeias globais de valor e interdependência econômica.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q027","area":"Humanas","subject":"Geografia","topic":"Energia e meio ambiente","context":"Uma cidade pretende diversificar sua matriz elétrica com fontes renováveis. Entre as propostas, está instalar painéis solares em telhados de escolas, reduzindo parte do consumo da rede durante o dia.","stem":"Uma limitação técnica dessa proposta é","options":["a produção não depender das condições de iluminação.","a energia solar ser obrigatoriamente produzida por combustão.","a geração ocorrer de modo constante em qualquer horário.","a impossibilidade de produzir eletricidade em ambientes urbanos.","a variação da geração conforme a incidência de radiação solar."],"answer":4,"explanation":"A geração fotovoltaica depende da luz incidente e varia com horário, clima e localização.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q028","area":"Humanas","subject":"Geografia","topic":"Agricultura e território","context":"Em determinada região, a expansão de monoculturas de exportação ocorre acompanhada de maior mecanização. Pequenos produtores relatam elevação do preço da terra e pressão para vender suas propriedades.","stem":"Uma questão socioespacial relacionada a esse processo é","options":["o desaparecimento de todos os mercados externos.","a concentração fundiária e os conflitos pelo uso da terra.","a redução obrigatória da produtividade agrícola.","a ausência de impactos sobre o emprego rural.","a garantia de distribuição igualitária de terras."],"answer":1,"explanation":"A expansão de atividades em grande escala pode intensificar concentração da terra e disputas territoriais.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q029","area":"Humanas","subject":"Filosofia","topic":"Ética e cidadania","context":"Um conselho escolar discute como distribuir recursos escassos entre acessibilidade, biblioteca e equipamentos esportivos. O debate inclui os estudantes afetados e exige justificar as escolhas em critérios públicos.","stem":"Uma prática alinhada à ética democrática nesse caso é","options":["priorizar interesses pessoais de quem preside a reunião.","impedir a manifestação de grupos minoritários.","decidir sem divulgar critérios para evitar contestação.","considerar diferentes necessidades e justificar decisões coletivamente.","substituir a participação por decisões arbitrárias."],"answer":3,"explanation":"A deliberação democrática pressupõe participação, argumentação pública e consideração de direitos e necessidades.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q030","area":"Humanas","subject":"Sociologia","topic":"Desigualdade social","context":"Uma pesquisa mostra que estudantes com acesso estável à internet, espaço silencioso e livros costumam enfrentar condições diferentes de estudo em relação àqueles sem esses recursos.","stem":"O exemplo evidencia principalmente","options":["a influência das condições materiais nas oportunidades educacionais.","a inexistência de fatores sociais na educação.","a igualdade automática de recursos entre todos os estudantes.","a eliminação de desigualdades pelo uso exclusivo de avaliações.","a irrelevância do ambiente doméstico no processo de aprendizagem."],"answer":0,"explanation":"Condições materiais e sociais podem ampliar ou restringir oportunidades educacionais.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q031","area":"Humanas","subject":"Sociologia","topic":"Cultura e identidade","context":"Em uma cidade, grupos de imigrantes organizam eventos culinários, musicais e linguísticos, mantendo práticas de origem e criando novas tradições em contato com outros moradores.","stem":"O fenômeno pode ser compreendido como","options":["prova de que culturas são isoladas e imutáveis.","eliminação obrigatória das tradições locais.","interação cultural e reconstrução de identidades.","perda automática de todas as memórias coletivas.","impossibilidade de convivência entre grupos distintos."],"answer":2,"explanation":"Culturas se transformam pelo contato e por processos de identificação e pertencimento.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q032","area":"Humanas","subject":"Geografia","topic":"Cartografia e escalas","context":"Um mapa escolar de escala 1:100.000 representa uma estrada retilínea com um segmento de 3 cm.","stem":"A distância real aproximada representada pelo segmento é","options":["300 m.","30 km.","100 km.","3 m.","3 km."],"answer":4,"explanation":"Cada 1 cm representa 100.000 cm = 1 km. Logo, 3 cm representam 3 km.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q033","area":"Natureza","subject":"Biologia","topic":"Citologia e metabolismo","context":"Células musculares exigem energia para contração. Durante exercício aeróbio, moléculas orgânicas são oxidadas e a célula produz ATP em etapas que envolvem uma organela específica.","stem":"A organela diretamente associada à maior parte da produção de ATP nesse processo é a","options":["mitocôndria.","complexo de Golgi.","lisossomo.","vacúolo.","ribossomo."],"answer":0,"explanation":"A mitocôndria participa da respiração celular aeróbia e produz grande parte do ATP usado pelas células.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q034","area":"Natureza","subject":"Biologia","topic":"Ecologia e energia","context":"Em um ambiente de campo, plantas são consumidas por gafanhotos, que servem de alimento a sapos; cobras podem predar os sapos. O fluxo de energia segue o sentido indicado no esquema.","stem":"Qual organismo ocupa o nível de consumidor secundário nessa cadeia?","options":["Plantas.","Gafanhotos.","Sapos.","Cobras.","Decompositores."],"answer":2,"explanation":"Plantas são produtores; gafanhotos, consumidores primários; sapos, secundários; cobras, terciários.","visual":{"type":"chain","labels":["Plantas","Gafanhotos","Sapos","Cobras"]},"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q035","area":"Natureza","subject":"Biologia","topic":"Vacinação e imunidade","context":"Uma campanha de saúde coletiva orienta a manter a vacinação em dia. Parte da proteção produzida por uma vacina envolve memória imunológica, que facilita respostas futuras ao mesmo agente.","stem":"A característica descrita depende principalmente","options":["da eliminação permanente de todos os microrganismos do ambiente.","da substituição da alimentação por imunizantes.","da produção de energia pelas hemácias.","da indução de resposta específica e formação de células de memória.","da ausência de participação de células do sistema imune."],"answer":3,"explanation":"Vacinas podem estimular resposta imune adaptativa e células de memória, favorecendo respostas mais rápidas e específicas em novas exposições.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q036","area":"Natureza","subject":"Biologia","topic":"Genética mendeliana","context":"Em uma espécie vegetal, o alelo A é dominante sobre a. Dois indivíduos heterozigotos (Aa) são cruzados. Considere segregação mendeliana simples.","stem":"A probabilidade de produzir um descendente com genótipo aa é","options":["0%.","25%.","50%.","75%.","100%."],"answer":1,"explanation":"No cruzamento Aa × Aa, os genótipos esperados são AA, Aa, Aa e aa; um em quatro é aa: 25%.","visual":{"type":"punnett","top":["A","a"],"side":["A","a"]},"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q037","area":"Natureza","subject":"Biologia","topic":"Poluição e saneamento","context":"Após o lançamento de esgoto sem tratamento em um rio, observou-se aumento de matéria orgânica e proliferação de microrganismos decompositores. Em seguida, ocorreu morte de peixes por falta de oxigênio.","stem":"O fator mais diretamente relacionado à diminuição do oxigênio dissolvido é","options":["o aumento da radiação solar provocado pela matéria orgânica.","a interrupção completa da fotossíntese em todas as plantas.","a diminuição da temperatura da água pela decomposição.","a produção de gás oxigênio pela fermentação.","o consumo de oxigênio na decomposição da matéria orgânica."],"answer":4,"explanation":"Microrganismos aeróbios consomem oxigênio para decompor a matéria orgânica, podendo provocar hipóxia na água.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q038","area":"Natureza","subject":"Biologia","topic":"Fotossíntese e respiração","context":"Um estudante afirma que plantas não realizam respiração celular porque produzem glicose pela fotossíntese. A professora explica que ambos os processos ocorrem no metabolismo vegetal.","stem":"A correção da professora se fundamenta no fato de que","options":["a respiração celular ajuda a disponibilizar energia na forma de ATP.","a fotossíntese impede a existência de mitocôndrias.","a glicose não pode participar do metabolismo vegetal.","o oxigênio é totalmente desnecessário às plantas.","a fotossíntese ocorre exclusivamente na ausência de luz."],"answer":0,"explanation":"Plantas fazem fotossíntese, mas também utilizam a respiração celular para produzir ATP a partir de moléculas orgânicas.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q039","area":"Natureza","subject":"Química","topic":"Separação de misturas","context":"Uma comunidade retira água de um reservatório com partículas de areia em suspensão. Antes do tratamento final, o sistema precisa separar parte desse material sólido insolúvel da água.","stem":"O método adequado para essa etapa é","options":["destilação fracionada para separar gases.","eletrólise para transformar a areia.","filtração, que retém partículas sólidas no meio filtrante.","sublimação da água a temperatura ambiente.","fusão da areia para obter água potável."],"answer":2,"explanation":"A filtração separa sólidos insolúveis em suspensão do líquido. Potabilidade depende também de etapas adicionais.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q040","area":"Natureza","subject":"Química","topic":"pH e concentração","context":"Duas soluções aquosas a 25 °C apresentam pH 3 e pH 5. A definição de pH relaciona-se ao logaritmo negativo da concentração de íons H+.","stem":"A solução de pH 3 apresenta concentração de H+ aproximadamente","options":["2 vezes maior.","10 vezes maior.","20 vezes maior.","100 vezes maior.","1000 vezes menor."],"answer":3,"explanation":"A escala de pH é logarítmica. Diferença de 2 unidades indica 10² = 100 vezes maior concentração de H+ na solução de menor pH.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q041","area":"Natureza","subject":"Química","topic":"Estequiometria","context":"Na formação da água, a equação balanceada é 2 H₂ + O₂ → 2 H₂O. Admita condições ideais, reagentes puros e ausência de perdas.","stem":"Para consumir completamente 6 mol de H₂, a quantidade necessária de O₂ é","options":["1 mol.","3 mol.","6 mol.","9 mol.","12 mol."],"answer":1,"explanation":"A relação estequiométrica é 2 mol de H₂ para 1 mol de O₂. Para 6 mol de H₂: 6 × (1/2) = 3 mol de O₂.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q042","area":"Natureza","subject":"Química","topic":"Densidade","context":"Em um experimento, dois líquidos não miscíveis são colocados no mesmo recipiente. O líquido A, de densidade 0,80 g/mL, forma a camada superior; o líquido B apresenta densidade 1,10 g/mL.","stem":"A disposição observada ocorre porque","options":["o líquido A apresenta maior densidade e afunda.","o líquido B evapora completamente.","a densidade é igual nos dois líquidos.","o líquido B sempre fica acima por conter mais massa total.","o líquido menos denso tende a ficar sobre o mais denso."],"answer":4,"explanation":"Em equilíbrio, líquidos imiscíveis de menor densidade tendem a ficar sobre os de maior densidade, como A sobre B.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q043","area":"Natureza","subject":"Física","topic":"Cinemática","context":"Um ônibus percorre 180 km por uma estrada, mantendo velocidade média de 60 km/h durante o percurso. Desconsidere paradas.","stem":"O tempo necessário para completar o trajeto é","options":["3 horas.","2 horas.","4 horas.","6 horas.","120 horas."],"answer":0,"explanation":"t = distância / velocidade = 180 km / (60 km/h) = 3 h.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q044","area":"Natureza","subject":"Física","topic":"Energia elétrica","context":"Uma lâmpada LED de potência 10 W fica ligada 5 horas por dia durante 30 dias. Para estimar o consumo de energia, usa-se potência × tempo.","stem":"O consumo de energia elétrica no período é","options":["0,15 kWh.","0,5 kWh.","1,5 kWh.","15 kWh.","150 kWh."],"answer":2,"explanation":"10 W = 0,01 kW. Tempo total = 5 × 30 = 150 h. Consumo = 0,01 × 150 = 1,5 kWh.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q045","area":"Natureza","subject":"Física","topic":"Lei de Ohm","context":"Um resistor ideal de 6 Ω é ligado a uma fonte de tensão contínua de 12 V. Considere o circuito simples representado.","stem":"A intensidade da corrente elétrica que atravessa o resistor é","options":["0,5 A.","1 A.","1,5 A.","2 A.","6 A."],"answer":3,"explanation":"Pela Lei de Ohm, I = V/R = 12/6 = 2 A.","visual":{"type":"circuit","voltage":"12 V","resistance":"6 Ω"},"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q046","area":"Natureza","subject":"Física","topic":"Calorimetria","context":"Duas amostras de água com a mesma massa recebem a mesma quantidade de calor, sem perdas para o ambiente. A amostra A começa a 20 °C e a B a 30 °C.","stem":"Considerando o calor específico constante, qual conclusão é adequada?","options":["A amostra A necessariamente termina mais quente que a B.","As duas amostras sofrem a mesma variação de temperatura.","A amostra B não pode absorver energia.","A amostra A terá variação de temperatura igual a zero.","A amostra com menor temperatura inicial recebe mais calor."],"answer":1,"explanation":"Pela relação Q = m c ΔT, para o mesmo Q, mesma massa m e mesmo calor específico c, a variação ΔT é igual nas duas amostras.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q047","area":"Natureza","subject":"Física","topic":"Gráficos de movimento","context":"O gráfico representa a posição de um ciclista em função do tempo ao longo de um trecho retilíneo. Os dados mostram posição 0 m no instante 0 s e 80 m no instante 20 s.","stem":"A velocidade média nesse intervalo é","options":["2 m/s.","3 m/s.","5 m/s.","8 m/s.","4 m/s."],"answer":4,"explanation":"Velocidade média = Δposição / Δtempo = (80-0)/(20-0) = 4 m/s.","visual":{"type":"line","title":"Posição do ciclista","labels":["0","5","10","15","20"],"values":[0,20,40,60,80],"x":"Tempo (s)","y":"Posição (m)"},"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q048","area":"Natureza","subject":"Química","topic":"Química orgânica e ambiente","context":"Na fabricação de biocombustíveis, uma etapa pode envolver reações de compostos orgânicos que apresentam diferentes grupos funcionais. O etanol, utilizado como combustível, possui o grupo hidroxila ligado a carbono saturado.","stem":"Por sua classificação funcional, o etanol pertence à família dos","options":["ésteres.","aldeídos.","ácidos carboxílicos.","álcoois.","éteres."],"answer":3,"explanation":"O etanol tem grupo —OH ligado a carbono saturado, característica de álcool.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q049","area":"Matemática","subject":"Matemática","topic":"Porcentagem","context":"Uma loja divulga uma campanha de desconto de 20% sobre um tênis anunciado por R$ 250,00. O valor do desconto é calculado sobre o preço original.","stem":"O valor a ser pago pelo cliente, sem outras taxas, é","options":["R$ 50,00.","R$ 180,00.","R$ 200,00.","R$ 220,00.","R$ 230,00."],"answer":2,"explanation":"20% de 250 = 50. Preço final: 250 − 50 = R$ 200,00.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q050","area":"Matemática","subject":"Matemática","topic":"Porcentagem sucessiva","context":"Um produto custa R$ 100,00. Em janeiro, seu preço sobe 10%; em fevereiro, o preço atualizado sofre redução de 10%.","stem":"O valor final do produto após as duas alterações é","options":["R$ 90,00.","R$ 99,00.","R$ 100,00.","R$ 101,00.","R$ 110,00."],"answer":1,"explanation":"100 × 1,10 = 110. Depois: 110 × 0,90 = 99. Aumento e desconto percentuais não se anulam porque as bases são diferentes.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q051","area":"Matemática","subject":"Matemática","topic":"Média e interpretação de dados","context":"Uma turma registrou quantos livros quatro estudantes leram em um trimestre, conforme o gráfico.","stem":"A média aritmética de livros lidos pelos quatro estudantes é","options":["2.","3.","4.","5.","6."],"answer":2,"explanation":"Valores: 2, 3, 5 e 6. Soma = 16, dividida por 4 = 4.","visual":{"type":"bar","title":"Livros lidos por estudante","labels":["Ana","Beto","Caio","Duda"],"values":[2,3,5,6],"unit":"livros"},"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q052","area":"Matemática","subject":"Matemática","topic":"Mediana","context":"O número de viagens de bicicleta realizadas em uma semana por cinco pessoas foi 1, 2, 2, 4 e 11. Um pesquisador busca uma medida de posição pouco afetada pelo valor extremo 11.","stem":"A mediana desse conjunto é","options":["1.","2.","4.","5.","11."],"answer":1,"explanation":"Os cinco valores já estão ordenados; a mediana é o terceiro valor: 2.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q053","area":"Matemática","subject":"Matemática","topic":"Geometria plana","context":"Uma escola vai instalar grama em um pátio retangular com 8 m de comprimento e 5 m de largura. Todo o pátio será coberto, sem descontos por canteiros.","stem":"A área que deverá receber grama é de","options":["13 m².","26 m².","35 m².","40 m².","80 m²."],"answer":3,"explanation":"Área do retângulo = comprimento × largura = 8 × 5 = 40 m².","visual":{"type":"rectangle","w":"8 m","h":"5 m"},"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q054","area":"Matemática","subject":"Matemática","topic":"Escalas","context":"Em uma planta de uma praça, a escala é 1:500. A distância entre dois portões aparece representada por um segmento de 6 cm.","stem":"A distância real entre esses portões é","options":["3 m.","12 m.","20 m.","30 m.","300 m."],"answer":3,"explanation":"6 cm × 500 = 3.000 cm = 30 metros.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q055","area":"Matemática","subject":"Matemática","topic":"Proporcionalidade","context":"Uma receita para quatro pessoas utiliza 300 g de farinha. Pretende-se preparar o mesmo prato para dez pessoas, mantendo constante a proporção dos ingredientes.","stem":"A massa de farinha necessária será de","options":["750 g.","600 g.","500 g.","900 g.","1.200 g."],"answer":0,"explanation":"300/4 = 75 g por pessoa; para 10 pessoas, 75 × 10 = 750 g.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q056","area":"Matemática","subject":"Matemática","topic":"Probabilidade","context":"Uma caixa contém 3 bolas azuis e 2 vermelhas, todas com mesmo tamanho. Uma bola é retirada ao acaso, sem observar sua cor.","stem":"A probabilidade de a bola retirada ser vermelha é","options":["1/5.","2/3.","3/5.","1/2.","2/5."],"answer":4,"explanation":"São 2 bolas vermelhas em 5 bolas possíveis, então P = 2/5 = 40%.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q057","area":"Matemática","subject":"Matemática","topic":"Função afim","context":"Uma empresa de transporte cobra tarifa fixa de R$ 6,00 mais R$ 2,00 por quilômetro rodado. O valor total V depende da distância d em quilômetros.","stem":"Qual expressão representa o preço da viagem?","options":["V = 6d + 2.","V = 2d − 6.","V = 6 + 2d.","V = 8d.","V = 12d."],"answer":2,"explanation":"A cobrança fixa soma R$ 6,00, e cada quilômetro acrescenta R$ 2,00: V(d) = 6 + 2d.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q058","area":"Matemática","subject":"Matemática","topic":"Juros compostos","context":"Uma aplicação de R$ 1.000,00 rende 10% ao mês, com capitalização composta, durante dois meses, sem taxas ou impostos.","stem":"O montante ao final do período será","options":["R$ 1.100,00.","R$ 1.200,00.","R$ 1.210,00.","R$ 1.220,00.","R$ 1.300,00."],"answer":2,"explanation":"M = 1000 × (1,10)² = 1000 × 1,21 = R$ 1.210,00.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q059","area":"Matemática","subject":"Matemática","topic":"Grandezas e unidades","context":"Um reservatório de uma escola armazena 2,5 m³ de água. Para informar a capacidade em litros, a equipe lembra que 1 m³ equivale a 1.000 litros.","stem":"A capacidade do reservatório é","options":["250 L.","500 L.","1.000 L.","2.000 L.","2.500 L."],"answer":4,"explanation":"2,5 m³ × 1.000 L/m³ = 2.500 litros.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q060","area":"Matemática","subject":"Matemática","topic":"Teorema de Pitágoras","context":"Uma escada de 5 m encosta em uma parede vertical. A base da escada fica a 3 m da parede, formando um triângulo retângulo com o chão.","stem":"A altura aproximada alcançada pela escada é","options":["4 m.","3 m.","5 m.","6 m.","8 m."],"answer":0,"explanation":"Pelo teorema de Pitágoras: h² + 3² = 5² → h² = 16 → h = 4 m.","visual":{"type":"triangle","a":"3 m","c":"5 m"},"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q061","area":"Matemática","subject":"Matemática","topic":"Volume de sólidos","context":"Uma caixa d’água em formato de paralelepípedo reto-retângulo mede 2 m de comprimento, 1,5 m de largura e 1 m de altura. Considere toda a capacidade interna útil.","stem":"O volume máximo de água que ela comporta é","options":["1,5 m³.","2 m³.","2,5 m³.","3 m³.","4,5 m³."],"answer":3,"explanation":"V = 2 × 1,5 × 1 = 3 m³, o equivalente a 3.000 litros.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q062","area":"Matemática","subject":"Matemática","topic":"Análise de gráficos","context":"O gráfico mostra a quantidade de atendimentos de um serviço em quatro dias. A equipe pretende identificar o dia de maior demanda.","stem":"Em qual dia ocorreu o maior número de atendimentos?","options":["Segunda-feira.","Quarta-feira.","Terça-feira.","Quinta-feira.","Todos iguais."],"answer":3,"explanation":"Pelo gráfico, os valores são segunda 22, terça 28, quarta 19 e quinta 34; quinta apresenta o maior valor.","visual":{"type":"bar","title":"Atendimentos por dia","labels":["Seg","Ter","Qua","Qui"],"values":[22,28,19,34],"unit":"atendimentos"},"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q063","area":"Matemática","subject":"Matemática","topic":"Sistema de equações","context":"Em uma papelaria, dois cadernos e uma caneta custam R$ 26,00. Um caderno e uma caneta custam R$ 16,00. Os preços unitários são constantes.","stem":"O preço de um caderno é","options":["R$ 8,00.","R$ 10,00.","R$ 12,00.","R$ 14,00.","R$ 16,00."],"answer":1,"explanation":"2c + p = 26; c + p = 16. Subtraindo a segunda equação da primeira: c = 10.","visual":null,"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"},{"id":"Q064","area":"Matemática","subject":"Matemática","topic":"Leitura de tabela","context":"Uma cooperativa mediu a massa de papel reciclado durante quatro semanas. O registro foi 25 kg na semana 1, 40 kg na semana 2, 35 kg na semana 3 e 50 kg na semana 4.","stem":"O total de papel reciclado no período foi","options":["125 kg.","135 kg.","140 kg.","150 kg.","160 kg."],"answer":3,"explanation":"25 + 40 + 35 + 50 = 150 kg.","visual":{"type":"table","title":"Coleta semanal de papel","headers":["Semana","Papel (kg)"],"rows":[["1","25"],["2","40"],["3","35"],["4","50"]]},"difficulty":"Média","origin":"Questão autoral","source":"Material original ENEM Intelligence — sem vínculo com o Inep"}];
